fn exec_update_version_upper_bound_inductive(pre: Self, post: Self, node_id: NodeId) {
    // The transition only changes version_upper_bound and combiner[node_id]
    // All other fields remain unchanged

    // Show post.invariant() by proving each invariant component
    // Most invariants follow from pre.invariant() since fields are unchanged

    // For inv_readonly_requests_wf: local_reads is unchanged
    assert(post.inv_readonly_requests_wf()) by {
        assert(forall |rid| #[trigger] post.local_reads.contains_key(rid) implies post.wf_readstate(post.local_reads[rid])) from pre.inv_readonly_requests_wf();
    }

    // For inv_read_results: need to show read_results_match holds with new version_upper_bound
    assert(post.inv_read_results()) by {
        assert(forall |rid| #[trigger] post.local_reads.contains_key(rid) implies post.read_results_match(post.local_reads[rid]));
    }

    // For combiner_states_wf: check the updated node_id and unchanged others
    assert(post.combiner_states_wf()) by {
        assert(forall |n| #[trigger] post.combiner.contains_key(n) implies post.wf_combiner_for_node_id(n));
    }

    // For inv_local_updates: local_updates is unchanged
    assert(post.inv_local_updates()) by {
        assert(forall |rid| #[trigger] post.local_updates.contains_key(rid) implies post.inv_local_updates_wf(post.local_updates[rid])) from pre.inv_local_updates();
    }

    // For inv_update_results: local_updates is unchanged, log is unchanged
    assert(post.inv_update_results()) by {
        assert(forall |rid| #[trigger] post.local_updates.contains_key(rid) implies post.update_results_match(post.local_updates[rid])) from pre.inv_update_results();
    }

    // For inv_combiner_rids_distinct: combiner changed only for node_id
    assert(post.inv_combiner_rids_distinct()) by {
        assert(forall |node_id1, node_id2|
            #[trigger] post.combiner.contains_key(node_id1)
            && #[trigger] post.combiner.contains_key(node_id2)
            && node_id1 != node_id2 implies
            seq_disjoint(post.combiner[node_id1].queued_ops(), post.combiner[node_id2].queued_ops()));
    }

    // For replica_state: replicas is unchanged
    assert(post.replica_state()) by {
        assert(forall |node_id| #[trigger] post.replicas.contains_key(node_id) implies post.replicas[node_id] == compute_nrstate_at_version(post.log, post.current_local_version(node_id)));
    }

    // For other invariants that don't involve changed fields
    assert(post.inv_version_in_range()) by {
        // version_upper_bound was updated to max(pre.version_upper_bound, tail)
        // tail <= pre.tail from pre-state, and pre.version_upper_bound <= pre.tail
        // so new version_upper_bound <= pre.tail = post.tail
    }

    assert(post.inv_local_version_upper_bound_heads()) by {
        assert(forall |node_id| #[trigger] post.local_versions.contains_key(node_id) implies post.local_versions[node_id] <= post.version_upper_bound);
    }

    assert(post.inv_log_complete()) by {
        // log and tail unchanged
    }
}

