    assert(post.inv_readonly_requests_wf()) by {
        assert(forall |rid| #[trigger] post.local_reads.contains_key(rid)
            implies post.wf_readstate(post.local_reads[rid])) {
            assert(pre.local_reads =~= post.local_reads);
            assert(pre.wf_readstate(pre.local_reads[rid]) == post.wf_readstate(post.local_reads[rid]));
        }
    }

    // For inv_read_results: need to show read_results_match holds with new version_upper_bound
    assert(post.inv_read_results()) by {
        assert(forall |rid| #[trigger] post.local_reads.contains_key(rid)
            implies post.read_results_match(post.local_reads[rid])) {
            let rid = rid;
            if post.local_reads.contains_key(rid) {
                let read_state = post.local_reads[rid];
                // local_reads is unchanged
                assert(pre.local_reads =~= post.local_reads);
                assert(pre.local_reads[rid] == post.local_reads[rid]);

                if read_state.is_Done() {
                    let done_read = read_state.get_Done();
                    let version_ub = done_read.version_upper_bound;
                    let op = done_read.op;
                    let ret = done_read.ret;

                    // From pre-state invariant
                    assert(pre.read_results_match(pre.local_reads[rid]));
                    // This gives us exists |v| rangeincl(version_ub, v, pre.version_upper_bound)
                    // and ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op)

                    // We need to show: exists |v| rangeincl(version_ub, v, post.version_upper_bound)
                    // Since post.version_upper_bound >= pre.version_upper_bound (it's max of pre.version_upper_bound and tail)
                    // and we have version_ub <= pre.version_upper_bound from pre-state,
                    // we have version_ub <= post.version_upper_bound

                    assert(exists |v: nat| rangeincl(version_ub, v, post.version_upper_bound)
                        && ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)) by {
                        // From pre-state: exists |v| rangeincl(version_ub, v, pre.version_upper_bound) && ...
                        // Since pre.version_upper_bound <= post.version_upper_bound,
                        // rangeincl(version_ub, v, pre.version_upper_bound) implies rangeincl(version_ub, v, post.version_upper_bound)
                        // for the same v
                        let pre_v = pre.read_results_match(post.local_reads[rid]).choose(|v| rangeincl(version_ub, v, pre.version_upper_bound) && 
                            ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op));
                        assert(rangeincl(version_ub, pre_v, post.version_upper_bound));
                        assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, pre_v), op));
                    }
                }
            }
        }
    }

