#[inductive(exec_update_version_upper_bound)]
fn exec_update_version_upper_bound_inductive(pre: Self, post: Self, node_id: NodeId) {
    // The transition only changes version_upper_bound and combiner[node_id]
    // All other fields remain unchanged

    // The post.invariant() follows from the pre.invariant() as most fields are unchanged
    assert(post.invariant()) by {
        // inv_request_ids_finite: domains unchanged
        assert(post.inv_request_ids_finite());

        // inv_local_combiner_complete: combiner dom unchanged
        assert(post.inv_local_combiner_complete());

        // inv_combiner_local_versions_domains: unchanged
        assert(post.combiner_local_versions_domains());

        // inv_combiner_replicas_domains: unchanged
        assert(post.combiner_replicas_domains());

        // inv_version_in_range: version_upper_bound <= tail
        // version_upper_bound was updated to max(pre.version_upper_bound, tail)
        // We need to show max(pre.version_upper_bound, tail) <= post.tail
        // From pre-state: pre.version_upper_bound <= pre.tail
        // From Loop state invariant: tail <= pre.tail
        // post.tail = pre.tail (unchanged)
        // So max(pre.version_upper_bound, tail) <= pre.tail = post.tail
        assert(post.inv_version_in_range());

        // inv_local_version_upper_bound_heads: local_versions <= version_upper_bound
        // local_versions unchanged, version_upper_bound increased, so this holds
        // For any node_id: pre.local_versions[node_id] <= pre.version_upper_bound <= post.version_upper_bound
        assert(post.inv_local_version_upper_bound_heads());

        // inv_readonly_requests_wf: local_reads is unchanged, wf_readstate holds
        // For Done states: version_upper_bound <= post.version_upper_bound
        // Since version_upper_bound <= pre.version_upper_bound <= post.version_upper_bound
        // and current_local_version unchanged for all nodes
        assert(post.inv_readonly_requests_wf());

        // inv_read_results: For Done states, need to show exists |v| version_upper_bound <= v <= post.version_upper_bound
        // From pre-state: exists |v| version_upper_bound <= v <= pre.version_upper_bound && ret == ...
        // Since pre.version_upper_bound <= post.version_upper_bound (it's max with tail)
        // We have version_upper_bound <= v <= pre.version_upper_bound <= post.version_upper_bound
        // So the same v works for post-state
        assert(post.inv_read_results()) by {
            // Need to show: forall |rid| post.local_reads.contains_key(rid) implies post.read_results_match(post.local_reads[rid])
            assert forall |rid| #[trigger] post.local_reads.contains_key(rid) implies post.read_results_match(post.local_reads[rid]) by {
                if post.local_reads.contains_key(rid) {
                    let read = post.local_reads[rid];
                    // local_reads is unchanged
                    assert(pre.local_reads.contains_key(rid));
                    assert(pre.local_reads[rid] == post.local_reads[rid]);

                    if read.is_Done() {
                        let done = read.get_Done();
                        let version_ub = done.version_upper_bound;
                        let op = done.op;
                        let ret = done.ret;

                        // From pre-state: exists |v| rangeincl(version_ub, v, pre.version_upper_bound) && ret == ...
                        // Need to show: exists |v| rangeincl(version_ub, v, post.version_upper_bound) && ret == ...

                        // From pre-state invariant inv_read_results
                        assert(pre.read_results_match(pre.local_reads[rid]));
                        // This gives us exists |v| rangeincl(version_ub, v, pre.version_upper_bound) && ret == ...
                        let v = pre.read_results_match(pre.local_reads[rid]).choose(|v| rangeincl(version_ub, v, pre.version_upper_bound) && 
                            ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op));

                        // We have: version_ub <= v <= pre.version_upper_bound
                        // And: pre.version_upper_bound <= post.version_upper_bound (since post.version_upper_bound = max(pre.version_upper_bound, tail))
                        // So: version_ub <= v <= post.version_upper_bound
                        assert(rangeincl(version_ub, v, post.version_upper_bound));

                        // compute_nrstate_at_version uses the log, which is unchanged
                        assert(compute_nrstate_at_version(pre.log, v) == compute_nrstate_at_version(post.log, v));
                        assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));
                    }
                }
            }
        }

        // combiner_states_wf: check the updated node_id
        assert(post.combiner_states_wf()) by {
            assert forall |n| #[trigger] post.combiner.contains_key(n) implies post.wf_combiner_for_node_id(n) by {
                if n == node_id {
                    // node_id was updated from Loop to UpdatedVersion
                    assert(post.combiner[node_id].is_UpdatedVersion());
                    let updated = post.combiner[node_id].get_UpdatedVersion();
                    // Need to show wf_combiner_for_node_id for UpdatedVersion state
                    // UpdatedVersion conditions:
                    // - tail <= post.version_upper_bound
                    // - post.local_versions[node_id] <= tail
                    // - LogContainsEntriesUpToHere(post.log, tail)
                    // - LogRangeNoNodeId(post.log, tail, post.tail, node_id)
                    // - QueueRidsUpdateDone(queued_ops, post.local_updates, queued_ops.len())
                    // - seq_unique(queued_ops)

                    // From pre-state Loop state conditions
                }
            }
        }

        // inv_local_updates: local_updates unchanged
        assert(post.inv_local_updates());

        // inv_update_results: local_updates and log unchanged
        assert(post.inv_update_results());

        // inv_combiner_rids_distinct: only node_id changed
        assert(post.inv_combiner_rids_distinct()) by {
            assert forall |node_id1, node_id2|
                #[trigger] post.combiner.contains_key(node_id1)
                && #[trigger] post.combiner.contains_key(node_id2)
                && node_id1 != node_id2 implies
                seq_disjoint(post.combiner[node_id1].queued_ops(), post.combiner[node_id2].queued_ops()) by {
                if node_id1 == node_id || node_id2 == node_id {
                    // One of them is the updated node
                    // Need to show the new queued_ops for the updated node is disjoint from all others
                }
            }
        }

        // replica_state: replicas unchanged, current_local_version for node_id changed
        assert(post.replica_state()) by {
            assert forall |n| #[trigger] post.replicas.contains_key(n) implies post.replicas[n] == compute_nrstate_at_version(post.log, post.current_local_version(n)) by {
                // For node_id, current_local_version changed to post.version_upper_bound (in UpdatedVersion state)
                // For other nodes, current_local_version unchanged
            }
        }

        // inv_log_complete: log and tail unchanged
        assert(post.inv_log_complete());
    }
}

